with parsed as (select id, created_at, items, attributes, array_contains(coupon_codes, 'SPRING10') as used_spring10, coalesce(attributes['utm_source'], 'none') as utm_source_or_default, array_max(transform(items, item -> item.price)) as max_item_price from carts) select id, created_at, used_spring10, utm_source_or_default, avg(max_item_price) over (order by cast(created_at as bigint) range between 1800 preceding and current row) as max_item_price_avg_30m, sum(max_item_price) over (order by max_item_price, id rows between unbounded preceding and current row) as running_max_item_price, avg(max_item_price) over (order by max_item_price, id rows between 6 preceding and 1 preceding) as max_item_price_avg_6_prior from parsed;
